package main

import (
	"gno.land/r/gov/dao"
	valset "gno.land/r/sys/validators/v0"
)

func main(cur realm) {
	r := valset.NewValidatorProposalRequest(
		cross(cur),
		[]valset.ValoperChange{
			valset.NewValoperChange(address("g1aeddlftlfk27ret5rf750d7w5dume3kcsm8r8m"), 60),
		},
		"Set validator gno-core-validator-1 to voting power 60",
		"Return gno-core-validator-1 to voting power 60: the other validators are signing again.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

package hex

import "sort"

// Board is the adjacency table of one game board. ids is sorted so lookups
// can binary-search it; nbr[i][d] is the index in ids of the neighbour of
// ids[i] in direction d, or -1 when the board edge lies that way.
//
// Boards are generated by scripts/gen_board_data.py and never mutated, so
// sharing *Board values is safe.
type Board struct {
	name      string
	ids       []string
	nbr       [][6]int
	qr        [][2]int // axial coordinates (q, r) of ids[i], see geom.gno
	fence     []uint8  // fenced hexsides of ids[i]: bit d for direction d (rule 35)
	obstacles []int    // indices of the obstacle hexes (rule 36)
	// between lists the hex pairs an obstacle lies between for the line of
	// sight (rule 31), computed by the generator from the printed coordinates
	// and the obstacle's outline on the board image: {a, b, o} with a < b
	// indices in ids and o an index in obstacles, sorted by (a, b, o).
	between [][3]int
}

// Name returns the board letter, e.g. "A".
func (b *Board) Name() string { return b.name }

// Size returns the number of hexes.
func (b *Board) Size() int { return len(b.ids) }

// Index returns the position of id in the sorted id list, or -1.
func (b *Board) Index(id string) int {
	i := sort.SearchStrings(b.ids, id)
	if i < len(b.ids) && b.ids[i] == id {
		return i
	}
	return -1
}

// Has reports whether id is a hex of this board.
func (b *Board) Has(id string) bool { return b.Index(id) >= 0 }

// Neighbor returns the hex adjacent to id in direction d. ok is false when
// id is unknown, d is invalid, or the board edge lies in that direction.
func (b *Board) Neighbor(id string, d Dir) (nb string, ok bool) {
	i := b.Index(id)
	if i < 0 || !d.Valid() {
		return "", false
	}
	j := b.nbr[i][d]
	if j < 0 {
		return "", false
	}
	return b.ids[j], true
}

// Neighbors returns the six neighbours of id in direction order; an empty
// string marks the board edge. An unknown id yields six empty strings.
func (b *Board) Neighbors(id string) [6]string {
	var out [6]string
	i := b.Index(id)
	if i < 0 {
		return out
	}
	for d, j := range b.nbr[i] {
		if j >= 0 {
			out[d] = b.ids[j]
		}
	}
	return out
}

// Fenced reports whether a fence or hitching post (rule 35) runs along the
// hexside of id in direction d, so that moving or staggering across it
// costs two delay cards.
func (b *Board) Fenced(id string, d Dir) bool {
	i := b.Index(id)
	if i < 0 || !d.Valid() || i >= len(b.fence) {
		return false
	}
	return b.fence[i]&(1<<uint(d)) != 0
}

// Obstacle reports whether id is an obstacle hex (rule 36: a trough, a
// table...), so that moving or staggering onto or off it costs two delay
// cards.
func (b *Board) Obstacle(id string) bool {
	i := b.Index(id)
	if i < 0 {
		return false
	}
	for _, o := range b.obstacles {
		if o == i {
			return true
		}
	}
	return false
}

// IDs returns a copy of the sorted hex ids.
func (b *Board) IDs() []string {
	out := make([]string, len(b.ids))
	copy(out, b.ids)
	return out
}

package hex

import "math"

// Axial step of each direction on the flat-top grid (q east along the
// columns, r down a column), matching scripts/gen_board_data.py.
var dirStep = [6][2]int{{0, -1}, {1, -1}, {1, 0}, {0, 1}, {-1, 1}, {-1, 0}}

// Step returns the axial (q, r) offset of one hex in direction d.
func (d Dir) Step() (q, r int) { return dirStep[d][0], dirStep[d][1] }

// Coords returns the axial coordinates of a hex.
func (b *Board) Coords(id string) (q, r int, ok bool) {
	i := b.Index(id)
	if i < 0 {
		return 0, 0, false
	}
	return b.qr[i][0], b.qr[i][1], true
}

// Distance is the range between two hexes in hexes along the shortest route
// over the board (rule 13.51), or -1 when either hex is unknown.
func (b *Board) Distance(from, to string) int {
	src, dst := b.Index(from), b.Index(to)
	if src < 0 || dst < 0 {
		return -1
	}
	if src == dst {
		return 0
	}
	dist := make([]int, len(b.ids))
	for i := range dist {
		dist[i] = -1
	}
	dist[src] = 0
	queue := []int{src}
	for len(queue) > 0 {
		i := queue[0]
		queue = queue[1:]
		for _, j := range b.nbr[i] {
			if j < 0 || dist[j] >= 0 {
				continue
			}
			dist[j] = dist[i] + 1
			if j == dst {
				return dist[j]
			}
			queue = append(queue, j)
		}
	}
	return -1
}

// InAimZone reports whether target lies in the aim zone of a character at
// from facing f (rule 8.32): its own hex and every hex in or between its
// ahead-left and ahead-right rows, i.e. the 120° cone spanned by those two
// directions.
func (b *Board) InAimZone(from string, f Dir, target string) bool {
	q0, r0, ok := b.Coords(from)
	q1, r1, ok2 := b.Coords(target)
	if !ok || !ok2 || !f.Valid() {
		return false
	}
	dq, dr := q1-q0, r1-r0
	uq, ur := Dir((int(f) + 5) % 6).Step() // ahead left
	wq, wr := Dir((int(f) + 1) % 6).Step() // ahead right
	// Solve a*u + b*w = d; the step vectors 120° apart have determinant ±1.
	det := uq*wr - ur*wq
	a := (dq*wr - dr*wq) / det
	c := (uq*dr - ur*dq) / det
	return a >= 0 && c >= 0
}

// LongDir is the direction from target that continues the line drawn from
// shooter through target (rule 14.32): the "Long" hex of a direction card is
// the target's neighbour that way. When the line runs between two hexes the
// one closest to it wins, lowest direction first; in a shared hex it is the
// shooter's facing.
func (b *Board) LongDir(shooter, target string, shooterFacing Dir) Dir {
	q0, r0, ok := b.Coords(shooter)
	q1, r1, ok2 := b.Coords(target)
	if !ok || !ok2 || (q0 == q1 && r0 == r1) {
		return shooterFacing
	}
	x, y := planar(q1-q0, r1-r0)
	best, bestCos := Dir(0), -2.0
	for d := 0; d < 6; d++ {
		sq, sr := Dir(d).Step()
		sx, sy := planar(sq, sr)
		cos := (x*sx + y*sy) / (math.Sqrt(x*x+y*y) * math.Sqrt(sx*sx+sy*sy))
		if cos > bestCos+1e-9 {
			best, bestCos = Dir(d), cos
		}
	}
	return best
}

// planar maps an axial offset to flat-top pixel-like coordinates (x east, y south).
func planar(q, r int) (x, y float64) {
	return 1.5 * float64(q), math.Sqrt(3) * (float64(r) + float64(q)/2)
}

// Package hex holds the pure hex geometry of the game: absolute directions,
// directions relative to a character's facing, and board adjacency tables.
package hex

// Dir is an absolute direction on a flat-top hex grid laid out in vertical
// columns: 0=N 1=NE 2=SE 3=S 4=SW 5=NW.
type Dir int

const (
	N Dir = iota
	NE
	SE
	S
	SW
	NW
)

var dirNames = [6]string{"N", "NE", "SE", "S", "SW", "NW"}

// Valid reports whether d is one of the six directions.
func (d Dir) Valid() bool { return d >= 0 && d < 6 }

// String returns the compass name of d.
func (d Dir) String() string {
	if !d.Valid() {
		return "?"
	}
	return dirNames[d]
}

// Opposite returns the direction pointing back at d.
func (d Dir) Opposite() Dir { return (d + 3) % 6 }

// Rel is a direction relative to a character's facing, as chosen on a move
// or turn card. The names are the ones the client and the plan string use.
// Same and Long only appear on the HEX line of result cards (direction
// cards, rule 14.3, relative to the target's body counter): they are not
// movement choices, ParseRel rejects them and Offset panics on them.
type Rel string

const (
	AheadLeft  Rel = "ahead_left"
	Ahead      Rel = "ahead"
	AheadRight Rel = "ahead_right"
	BackLeft   Rel = "back_left"
	Back       Rel = "back"
	BackRight  Rel = "back_right"
	Same       Rel = "same" // the target's own hex (14.33)
	Long       Rel = "long" // the hex beyond the target on the line from the shooter's hex through the target's (14.32)
)

// AheadRels are the three forward directions a move_ahead/turn_ahead card offers.
var AheadRels = [3]Rel{AheadLeft, Ahead, AheadRight}

// BackRels are the three backward directions a move_back/turn_back card offers.
var BackRels = [3]Rel{BackLeft, Back, BackRight}

// ParseRel converts a plan string token to a Rel.
func ParseRel(s string) (Rel, bool) {
	switch r := Rel(s); r {
	case AheadLeft, Ahead, AheadRight, BackLeft, Back, BackRight:
		return r, true
	}
	return "", false
}

// IsAhead reports whether r is one of the three forward directions.
func (r Rel) IsAhead() bool { return r == AheadLeft || r == Ahead || r == AheadRight }

// IsBack reports whether r is one of the three backward directions.
func (r Rel) IsBack() bool { return r == BackLeft || r == Back || r == BackRight }

// Offset is the number of 60° clockwise steps from the facing to r
// (ahead_left=5 ahead=0 ahead_right=1 back_right=2 back=3 back_left=4).
// Left and right are the character's own sides while it keeps facing
// forward: facing N, back_right is SE and back_left is SW.
func (r Rel) Offset() int {
	switch r {
	case Ahead:
		return 0
	case AheadRight:
		return 1
	case BackRight:
		return 2
	case Back:
		return 3
	case BackLeft:
		return 4
	case AheadLeft:
		return 5
	}
	panic("hex: invalid relative direction " + string(r))
}

// Resolve turns a relative direction into an absolute one for a facing.
func Resolve(facing Dir, r Rel) Dir {
	return Dir((int(facing) + r.Offset()) % 6)
}

// AheadDirs returns the absolute directions of ahead_left, ahead and
// ahead_right for a facing; these are also the aim-zone spokes (rule 8.32).
func AheadDirs(f Dir) [3]Dir {
	return [3]Dir{Resolve(f, AheadLeft), Resolve(f, Ahead), Resolve(f, AheadRight)}
}

// BackDirs returns the absolute directions of back_left, back and back_right.
func BackDirs(f Dir) [3]Dir {
	return [3]Dir{Resolve(f, BackLeft), Resolve(f, Back), Resolve(f, BackRight)}
}

package hex

import "sort"

// Height is the height of a counter or of a terrain feature for the line
// of sight (rule 31.3, the HEIGHTS table), at ground elevation: a higher
// number is higher on the map. Hill and gully elevations come with the
// boards that have them.
type Height int

const (
	// HeightDown is a DOWN body counter.
	HeightDown Height = 3
	// HeightObstacle is an obstacle (36.3) or a window sill (33.5).
	HeightObstacle Height = 4
	// HeightUpright is an upright counter, a counter on an obstacle (30.32)
	// and a hex aimed at (31.3).
	HeightUpright Height = 5
	// HeightWall is a wall or a treetrunk, higher than anything (33.2, 38.3).
	HeightWall Height = 10
)

// Between returns the obstacle hexes lying between two hexes for the line
// of sight (rule 31): those every string from one hex's printed coordinate
// to the other's passes through (31.2, 36.3), as the generator computed
// them from the board image into the between table. The order of the two
// hexes does not matter. It is nil when nothing lies between them, when
// they are the same hex or when either is unknown, and it never names one
// of the two hexes (36.5).
func (b *Board) Between(from, to string) []string {
	var out []string
	for _, o := range b.obstaclesBetween(b.Index(from), b.Index(to)) {
		out = append(out, b.ids[o])
	}
	return out
}

// obstaclesBetween is Between on indices: the obstacle hexes between ids[i] and
// ids[j], as indices in ids.
func (b *Board) obstaclesBetween(i, j int) []int {
	if i < 0 || j < 0 || i == j {
		return nil
	}
	if i > j {
		i, j = j, i
	}
	// The rows are sorted by (a, b, o): a pair's rows are contiguous.
	k := sort.Search(len(b.between), func(k int) bool {
		r := b.between[k]
		return r[0] > i || (r[0] == i && r[1] >= j)
	})
	var out []int
	for ; k < len(b.between) && b.between[k][0] == i && b.between[k][1] == j; k++ {
		out = append(out, b.obstacles[b.between[k][2]])
	}
	return out
}

// LineOfSight reports whether a character at from, of height hFrom, has a
// clear line of sight to a target at to, of height hTo (rule 31). Every
// obstacle lying between the two hexes is compared with the two heights
// (31.3): it blocks the sight when higher than both and not when lower
// than both (31.31); when it is between the two heights it blocks only if
// the lower end is adjacent to it (31.32; the plateau effect of 31.33
// needs hill or gully hexes, which no board has yet). The aim zone is not
// looked at here: 31.21 is InAimZone. blocker is the first obstacle
// blocking the sight, "" when it is clear or a hex is unknown (which
// blocks).
func (b *Board) LineOfSight(from, to string, hFrom, hTo Height) (clear bool, blocker string) {
	i, j := b.Index(from), b.Index(to)
	if i < 0 || j < 0 {
		return false, ""
	}
	for _, o := range b.obstaclesBetween(i, j) {
		if blocks(HeightObstacle, hFrom, hTo, b.adjacent(i, o), b.adjacent(j, o)) {
			return false, b.ids[o]
		}
	}
	return true, ""
}

// blocks applies rules 31.31 and 31.32 to a feature of height h lying
// between two counters of heights h1 and h2, each adjacent to it or not.
func blocks(h, h1, h2 Height, adj1, adj2 bool) bool {
	switch {
	case h > h1 && h > h2:
		return true // higher than both (31.31)
	case h < h1 && h < h2:
		return false // lower than both (31.31)
	case h1 < h:
		return adj1 // the lower counter blocks the sight when adjacent (31.32)
	case h2 < h:
		return adj2
	}
	return false
}

// adjacent reports whether ids[j] is a neighbour of ids[i].
func (b *Board) adjacent(i, j int) bool {
	for _, n := range b.nbr[i] {
		if n == j {
			return true
		}
	}
	return false
}

// Package cards holds the static definition of the 12 action cards, each with
// a front and a back side (24 actions), as printed in the 1982 game.
package cards

// Code identifies the action printed on one side of a card.
type Code string

const (
	Advance      Code = "advance"
	BackUp       Code = "back_up"
	Run          Code = "run"
	SpinAround   Code = "spin_around"
	Sprint       Code = "sprint"
	Turn         Code = "turn"
	LeapDrop     Code = "leap_drop"
	CockAimShoot Code = "cock_aim_shoot"
	GetUpDown    Code = "get_up_down"
	Throw        Code = "throw"
	Shoot        Code = "shoot"
	Strength     Code = "strength"
	Load         Code = "load"
	HeadOutBack  Code = "head_out_back"
	DrawAndCock  Code = "draw_and_cock"
	Jab          Code = "jab"
	Duck         Code = "duck"
	Swing        Code = "swing"
	Block        Code = "block"
	Belt         Code = "belt"
	Guard        Code = "guard"
)

// Kind is the card category (rule 5.2).
type Kind int

const (
	KindFoot Kind = iota
	KindHand
	KindAttack
	KindDefense
	KindStrength
)

// Choice is what the player must decide when selecting a side.
type Choice int

const (
	ChoiceNone Choice = iota
	ChoiceMoveAhead
	ChoiceMoveBack
	ChoiceTurnAhead
	ChoiceTurnBack
	ChoiceTargetRanged
	ChoiceTargetMelee
	ChoiceTargetDefend
	// ChoiceGun picks one of the character's holstered guns (Draw & Cock).
	ChoiceGun
)

// NeedsRel reports whether the choice is a relative direction (move or turn).
func (c Choice) NeedsRel() bool { return c.IsAheadRel() || c.IsBackRel() }

// IsAheadRel reports whether the choice is one of the three forward directions.
func (c Choice) IsAheadRel() bool { return c == ChoiceMoveAhead || c == ChoiceTurnAhead }

// IsBackRel reports whether the choice is one of the three backward directions.
func (c Choice) IsBackRel() bool { return c == ChoiceMoveBack || c == ChoiceTurnBack }

// NeedsGun reports whether the choice is a gun slot.
func (c Choice) NeedsGun() bool { return c == ChoiceGun }

// Side is one face of a card.
type Side struct {
	Code   Code
	Name   string
	Kind   Kind
	Cost   int // time points: the sequences the action takes
	Choice Choice
}

// Card is one physical card; its two sides cannot both be played in a turn.
type Card struct {
	Number int
	Front  Side
	Back   Side
}

// Side selectors as used in the plan string.
const (
	FrontSide byte = 'f'
	BackSide  byte = 'b'
)

// Cards is the deck, indexed by Number-1.
var Cards = [12]Card{
	{1, Side{Advance, "Advance", KindFoot, 2, ChoiceMoveAhead}, Side{BackUp, "Back Up", KindFoot, 3, ChoiceMoveBack}},
	{2, Side{Run, "Run", KindFoot, 1, ChoiceMoveAhead}, Side{SpinAround, "Spin Around", KindFoot, 2, ChoiceTurnBack}},
	{3, Side{Sprint, "Sprint", KindFoot, 1, ChoiceNone}, Side{Turn, "Turn", KindFoot, 1, ChoiceTurnAhead}},
	{4, Side{Sprint, "Sprint", KindFoot, 1, ChoiceNone}, Side{LeapDrop, "Leap/Drop", KindFoot, 1, ChoiceNone}},
	{5, Side{CockAimShoot, "Cock/Aim/Shoot", KindHand, 2, ChoiceTargetRanged}, Side{GetUpDown, "Get Up/Down", KindFoot, 3, ChoiceNone}},
	{6, Side{CockAimShoot, "Cock/Aim/Shoot", KindHand, 2, ChoiceTargetRanged}, Side{Throw, "Throw", KindHand, 2, ChoiceTargetRanged}},
	{7, Side{Shoot, "Shoot", KindHand, 1, ChoiceTargetRanged}, Side{Strength, "Strength", KindStrength, 2, ChoiceNone}},
	{8, Side{Load, "Load", KindHand, 3, ChoiceNone}, Side{HeadOutBack, "Head Out/Back", KindFoot, 2, ChoiceNone}},
	{9, Side{DrawAndCock, "Draw & Cock", KindHand, 3, ChoiceGun}, Side{HeadOutBack, "Head Out/Back", KindFoot, 2, ChoiceNone}},
	{10, Side{Jab, "Jab", KindAttack, 2, ChoiceTargetMelee}, Side{Duck, "Duck", KindDefense, 1, ChoiceTargetDefend}},
	{11, Side{Swing, "Swing", KindAttack, 3, ChoiceTargetMelee}, Side{Block, "Block", KindDefense, 2, ChoiceTargetDefend}},
	{12, Side{Belt, "Belt", KindAttack, 3, ChoiceTargetMelee}, Side{Guard, "Guard", KindDefense, 2, ChoiceTargetDefend}},
}

// Lookup returns the side of card number (1-12) selected by 'f' or 'b'.
func Lookup(number int, side byte) (Side, bool) {
	if number < 1 || number > len(Cards) {
		return Side{}, false
	}
	switch side {
	case FrontSide:
		return Cards[number-1].Front, true
	case BackSide:
		return Cards[number-1].Back, true
	}
	return Side{}, false
}

// Enabled reports whether the action is implemented by the engine: the foot
// actions, Draw & Cock, Cock/Aim/Shoot, Shoot, Load, Throw and Strength;
// brawling comes later.
func Enabled(c Code) bool {
	switch c {
	case Advance, BackUp, Run, SpinAround, Sprint, Turn, LeapDrop, GetUpDown, DrawAndCock, CockAimShoot, Shoot, Load, Throw, Strength:
		return true
	}
	return false
}

// IsShooting reports whether the action is played with a gun in hand: it
// takes a shoot option (cock, uncock, aim, shoot, nothing) and names the
// target (rules 11.3, 11.31).
func IsShooting(c Code) bool { return c == CockAimShoot || c == Shoot }

// TakesTarget reports whether the action may name a target, a hex or a
// character: the gun actions and Throw (11.31, 17.11).
func TakesTarget(c Code) bool { return IsShooting(c) || c == Throw }

// IsMove reports whether the action moves the character to another hex.
func IsMove(c Code) bool {
	return c == Advance || c == Run || c == BackUp || c == Sprint
}

package engine

// CharKeys are the 48 character tokens a player can pick.
var CharKeys = []string{
	"andy", "axe", "banker", "barkeep", "border_rider", "cattle_baron",
	"chief", "clerk", "driver", "dude", "eagle", "el_jefe", "fast_draw",
	"fast_eddie", "floozy", "foreman", "gambler", "guard", "gun_artist",
	"happy", "hawk", "ike", "innocente", "john_henry", "lady", "lightning",
	"ling_ho", "little_ernie", "lucky", "marshal", "mountain_man", "nco",
	"old_man", "owner", "prospector", "quiet_man", "reb", "running_boy",
	"slim", "smith", "sodbuster", "texas", "the_drifter", "the_kid",
	"u_s_scout", "veteran", "woman", "yankee",
}

// IsCharKey reports whether s names one of the character tokens.
func IsCharKey(s string) bool {
	for _, k := range CharKeys {
		if k == s {
			return true
		}
	}
	return false
}

package engine

import (
	"crypto/sha256"
	"encoding/binary"
	"math/rand"
	"strings"

	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/hex/v0"
)

// Result is one line of a result card: a number of points, or a named
// penalty (rules 14.1, 14.21). Points are 0 or more; penalties are negative.
type Result int

const (
	// LoseAim: the character loses its aim (no aim is tracked yet).
	LoseAim Result = -1
	// WildShot: every cocked gun goes off without hitting anything, is
	// uncocked and loses a shell; the aim is lost.
	WildShot Result = -2
	// Drop: an upright character turns DOWN, draws 3 delay cards and loses
	// its aim; no effect when already DOWN.
	Drop Result = -3
)

// IsPoints reports whether the line is a number of points.
func (r Result) IsPoints() bool { return r >= 0 }

// String returns the penalty name used in events and JSON, or "" for points.
func (r Result) String() string {
	switch r {
	case LoseAim:
		return "lose_aim"
	case WildShot:
		return "wild_shot"
	case Drop:
		return "drop"
	}
	return ""
}

// ResultCard is one of the 108 result cards (rule 2.4): N is its number on
// the card. Delay and Wound are the DELAY and WOUND lines and Hex the HEX
// line (direction cards, 14.3: a relative direction, hex.Same or hex.Long).
// The upper block is either a FIRE hit chart with its Target Status letters
// (cards 1-100, see fire.gno) or a MALFUNCTION block (cards 101-108). The
// TAC line (optional rule 9) is not used by this game.
type ResultCard struct {
	N      int
	Delay  Result
	Wound  Result
	Hex    hex.Rel
	Fire   *Chart       // the hit chart of a FIRE card, nil on a MALFUNCTION
	Status string       // Target Status letters of a FIRE card (StatusMove...)
	Malf   *Malfunction // the block of a MALFUNCTION card, nil on a FIRE card
}

// IsFire reports whether the card is a FIRE card (13.2).
func (c ResultCard) IsFire() bool { return c.Malf == nil }

// DeckSize is the number of result cards.
const DeckSize = 108

// Cards is the result deck in card order, index 0 = card 1.
var Cards = buildCards()

func buildCards() (cards [DeckSize]ResultCard) {
	// Each row is a run of consecutive cards sharing the same three lines,
	// transcribed from the card images (assets/result_card_NNN.png).
	runs := []struct {
		from, to     int
		delay, wound Result
		hex          hex.Rel
	}{
		{1, 18, 0, 0, hex.Same},
		{19, 36, 0, 1, hex.Long},
		{37, 54, 1, 2, hex.Long},
		{55, 60, 1, 3, hex.AheadLeft},
		{61, 69, 2, 3, hex.Same},
		{70, 78, 2, 4, hex.Long},
		{79, 84, 2, 5, hex.AheadRight},
		{85, 87, 2, 6, hex.Ahead},
		{88, 93, LoseAim, 1, hex.BackRight},
		{94, 99, LoseAim, WildShot, hex.BackLeft},
		{100, 100, WildShot, Drop, hex.Back},
		{101, 103, WildShot, Drop, hex.Back},
		{104, 106, 1, Drop, hex.Ahead},
		{107, 108, Drop, Drop, hex.Back},
	}
	n := 0
	for _, r := range runs {
		for i := r.from; i <= r.to; i++ {
			c := ResultCard{N: i, Delay: r.delay, Wound: r.wound, Hex: r.hex}
			if i <= len(fireCards) {
				c.Fire = parseChart(fireCards[i-1].chart)
				c.Status = fireCards[i-1].status
			} else {
				c.Malf = &malfunctions[i-1-len(fireCards)]
			}
			cards[i-1] = c
			n++
		}
	}
	if n != DeckSize {
		panic("result deck: wrong card count")
	}
	return cards
}

// Card returns result card n (1 to 108).
func Card(n int) ResultCard { return Cards[n-1] }

// Drawer hands out result cards to Resolve.
type Drawer interface {
	// Draw returns the next result card.
	Draw() ResultCard
}

// Seed hashes the given parts into shuffle seed material.
func Seed(parts ...string) [32]byte {
	return sha256.Sum256([]byte(strings.Join(parts, "|")))
}

// Deck is the result deck shuffled once from a seed and dealt in order
// (rule 5.7: the deck is reshuffled when exhausted). The same seed always
// deals the same cards, so a turn can be replayed from its stored seed.
type Deck struct {
	r     *rand.Rand
	order [DeckSize]int // card numbers in deal order
	next  int
	drawn []int // every card dealt so far, in order
}

// NewDeck shuffles the 108 cards with the seed.
func NewDeck(seed [32]byte) *Deck {
	s1 := binary.BigEndian.Uint64(seed[0:8])
	s2 := binary.BigEndian.Uint64(seed[8:16])
	d := &Deck{r: rand.New(rand.NewPCG(s1, s2))}
	d.shuffle()
	return d
}

func (d *Deck) shuffle() {
	for i := range d.order {
		d.order[i] = i + 1
	}
	d.r.Shuffle(DeckSize, func(i, j int) { d.order[i], d.order[j] = d.order[j], d.order[i] })
	d.next = 0
}

// Draw implements Drawer: the next card of the shuffle, reshuffling the
// whole deck once every card has been dealt.
func (d *Deck) Draw() ResultCard {
	if d.next >= DeckSize {
		d.shuffle()
	}
	c := Cards[d.order[d.next]-1]
	d.next++
	d.drawn = append(d.drawn, c.N)
	return c
}

// Order returns the card numbers in the order the deck deals them.
func (d *Deck) Order() [DeckSize]int { return d.order }

// Drawn returns the numbers of every card dealt so far, in order: the trace
// of a turn's draws.
func (d *Deck) Drawn() []int { return d.drawn }

// Fixed is a Drawer that always deals the same card; tests use Fixed(37)
// (DELAY 1) to match the BGA reference engine's stub.
type Fixed int

// Draw implements Drawer.
func (f Fixed) Draw() ResultCard { return Card(int(f)) }

// Sequence is a Drawer dealing the given card numbers in order, then the
// last one forever; for tests.
type Sequence []int

// Draw implements Drawer.
func (s *Sequence) Draw() ResultCard {
	q := *s
	n := q[0]
	if len(q) > 1 {
		*s = q[1:]
	}
	return Card(n)
}

package engine

import (
	"strconv"
	"strings"

	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/cards/v0"
	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/hex/v0"
)

// Compact text encodings of the engine's values, for what a realm keeps
// per turn: a struct stored on chain costs every field its type and
// value, so a turn's events as structs weigh over ten kilobytes, as one
// string a tenth of that. Fields are joined with '|', records with ';',
// gun slots with ',' and gun fields with ':'; none of the values (codes,
// hex ids, numbers) contain those characters. Decoding is lenient: a
// malformed number reads as 0, so a damaged record never breaks a view.

// EncodeEvents packs events into one string; DecodeEvents unpacks it.
func EncodeEvents(evs []Event) string {
	var b strings.Builder
	for i, e := range evs {
		if i > 0 {
			b.WriteByte(';')
		}
		b.WriteString(strings.Join([]string{
			strconv.Itoa(e.Seg), strconv.Itoa(e.Player), e.Kind, string(e.Action), e.From, e.To,
			strconv.Itoa(int(e.Facing)), boolStr(e.Down), strconv.Itoa(e.N), strconv.Itoa(e.Delay),
			e.Reason, strconv.Itoa(e.Card), e.Result, strconv.Itoa(e.Endurance), strconv.Itoa(e.Target),
			e.Hit, strconv.Itoa(e.Range), string(e.Gun), strconv.Itoa(e.GunID), strconv.Itoa(e.Step),
			e.Chart, e.Status,
		}, "|"))
	}
	return b.String()
}

// DecodeEvents unpacks what EncodeEvents produced.
func DecodeEvents(s string) []Event {
	if s == "" {
		return nil
	}
	recs := strings.Split(s, ";")
	evs := make([]Event, 0, len(recs))
	for _, r := range recs {
		f := strings.Split(r, "|")
		if len(f) != 22 {
			continue
		}
		evs = append(evs, Event{
			Seg: atoi(f[0]), Player: atoi(f[1]), Kind: f[2], Action: cards.Code(f[3]), From: f[4], To: f[5],
			Facing: hex.Dir(atoi(f[6])), Down: f[7] == "1", N: atoi(f[8]), Delay: atoi(f[9]),
			Reason: f[10], Card: atoi(f[11]), Result: f[12], Endurance: atoi(f[13]), Target: atoi(f[14]),
			Hit: f[15], Range: atoi(f[16]), Gun: GunType(f[17]), GunID: atoi(f[18]), Step: atoi(f[19]),
			Chart: f[20], Status: f[21],
		})
	}
	return evs
}

// EncodeCharacter packs a character, guns included; DecodeCharacter unpacks it.
func EncodeCharacter(c Character) string {
	guns := make([]string, 0, MaxGuns)
	for _, g := range c.Guns {
		if g.Type != NoGun {
			guns = append(guns, encodeGun(g))
		}
	}
	var killers [MaxPlayers]int
	for q, k := range c.Killers {
		if k {
			killers[q] = 1
		}
	}
	return strings.Join([]string{
		c.Hex, strconv.Itoa(int(c.Facing)), boolStr(c.Down), strconv.Itoa(c.Delay), strconv.Itoa(int(c.Status)),
		boolStr(c.PlayedFoot), boolStr(c.PlayedRun), boolStr(c.RanLastTurn), boolStr(c.Dropped),
		strconv.Itoa(c.Aim), c.AimHex, strconv.Itoa(c.Endurance), strconv.Itoa(c.Exhausted),
		strconv.Itoa(c.Serious), strconv.Itoa(c.GunArm), strconv.Itoa(c.OtherArm), strconv.Itoa(c.Leg),
		strings.Join(guns, ","),
		strconv.Itoa(c.AimAt), perSeat(killers), perSeat(c.SeriousFrom), perSeat(c.LegFrom),
		perSeat(c.Hurt),
	}, "|")
}

// perSeat packs one number per seat, "/"-separated.
func perSeat(v [MaxPlayers]int) string {
	s := make([]string, len(v))
	for i, n := range v {
		s[i] = strconv.Itoa(n)
	}
	return strings.Join(s, "/")
}

// seatValues unpacks what perSeat packed.
func seatValues(f string) (out [MaxPlayers]int) {
	if f == "" {
		return out
	}
	for i, n := range strings.Split(f, "/") {
		if i < MaxPlayers {
			out[i] = atoi(n)
		}
	}
	return out
}

// DecodeCharacter unpacks what EncodeCharacter produced.
func DecodeCharacter(s string) Character {
	f := strings.Split(s, "|")
	if len(f) != 23 {
		return Character{}
	}
	c := Character{
		Hex: f[0], Facing: hex.Dir(atoi(f[1])), Down: f[2] == "1", Delay: atoi(f[3]), Status: Status(atoi(f[4])),
		PlayedFoot: f[5] == "1", PlayedRun: f[6] == "1", RanLastTurn: f[7] == "1", Dropped: f[8] == "1",
		Aim: atoi(f[9]), AimHex: f[10], Endurance: atoi(f[11]), Exhausted: atoi(f[12]),
		Serious: atoi(f[13]), GunArm: atoi(f[14]), OtherArm: atoi(f[15]), Leg: atoi(f[16]),
		AimAt: atoi(f[18]),
	}
	for q, k := range seatValues(f[19]) {
		c.Killers[q] = k != 0
	}
	c.SeriousFrom = seatValues(f[20])
	c.LegFrom = seatValues(f[21])
	c.Hurt = seatValues(f[22])
	if f[17] != "" {
		for i, rec := range strings.Split(f[17], ",") {
			g, ok := decodeGun(rec)
			if i >= MaxGuns || !ok {
				break
			}
			c.Guns[i] = g
		}
	}
	return c
}

// EncodeChars packs the characters of a state (a turn's starting
// snapshot), seats in order; DecodeChars unpacks them.
func EncodeChars(cs []Character) string {
	parts := make([]string, len(cs))
	for i, c := range cs {
		parts[i] = EncodeCharacter(c)
	}
	return strings.Join(parts, ";")
}

// DecodeChars unpacks what EncodeChars produced.
func DecodeChars(s string) []Character {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ";")
	cs := make([]Character, len(parts))
	for i, part := range parts {
		cs[i] = DecodeCharacter(part)
	}
	return cs
}

// encodeGun packs a gun's fields, ':'-separated; decodeGun unpacks them.
func encodeGun(g Gun) string {
	return strings.Join([]string{
		strconv.Itoa(g.ID), string(g.Type), strconv.Itoa(int(g.Location)), boolStr(g.Cocked),
		strconv.Itoa(g.Shells), boolStr(g.Jammed), boolStr(g.Exploded),
	}, ":")
}

func decodeGun(s string) (Gun, bool) {
	g := strings.Split(s, ":")
	if len(g) != 7 {
		return Gun{}, false
	}
	return Gun{
		ID: atoi(g[0]), Type: GunType(g[1]), Location: GunLocation(atoi(g[2])), Cocked: g[3] == "1",
		Shells: atoi(g[4]), Jammed: g[5] == "1", Exploded: g[6] == "1",
	}, true
}

// EncodeGround packs the weapons lying on the board (a turn's ground at its
// start), ';'-separated records of id, hex and gun ("1|A-G6|1:colt45:0:0:6:0:0");
// DecodeGround unpacks them, skipping a malformed record.
func EncodeGround(ground []GroundGun) string {
	recs := make([]string, len(ground))
	for i, gg := range ground {
		recs[i] = strconv.Itoa(gg.ID) + "|" + gg.Hex + "|" + encodeGun(gg.Gun)
	}
	return strings.Join(recs, ";")
}

// DecodeGround unpacks what EncodeGround produced.
func DecodeGround(s string) []GroundGun {
	if s == "" {
		return nil
	}
	var out []GroundGun
	for _, rec := range strings.Split(s, ";") {
		f := strings.SplitN(rec, "|", 3)
		if len(f) != 3 {
			continue
		}
		if g, ok := decodeGun(f[2]); ok {
			out = append(out, GroundGun{ID: atoi(f[0]), Hex: f[1], Gun: g})
		}
	}
	return out
}

// EncodeInts packs numbers (the cards drawn in a turn); DecodeInts unpacks them.
func EncodeInts(ns []int) string {
	parts := make([]string, len(ns))
	for i, n := range ns {
		parts[i] = strconv.Itoa(n)
	}
	return strings.Join(parts, ",")
}

// DecodeInts unpacks what EncodeInts produced.
func DecodeInts(s string) []int {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	ns := make([]int, len(parts))
	for i, p := range parts {
		ns[i] = atoi(p)
	}
	return ns
}

func boolStr(b bool) string {
	if b {
		return "1"
	}
	return "0"
}

