}

// GamesJSON lists, for an address, the games with a free seat, the games
// being played (live: planning or revealing, for anyone to watch), the
// last endedLimit games finished (ended, for anyone to replay) and the
// games it plays or played, newest first (at most 50 each), with the
// address's registered name ("" if none). live and ended are found among
// the liveScan newest games, a running game being recent: a turn times
// out within days.
//
//	{"name","open":[summary...],"live":[summary...],"ended":[summary...],"mine":[summary...]}
//	summary = {"id","rev","phase","turn","maxTurns","timeout","winner","endReason","vp","stake","pot","payouts","houseCut","createdAt","updatedAt","timeoutAt","lockRound","players":[{"addr","name","char","status","committed","revealed"}]}
//
// lockRound (0 unless planning or revealing) tells the lobby when the
// timelocked plans of a seat committed and not revealed can be opened.
//
// players has one entry per seat, "addr" "" for a seat nobody took yet.
func GamesJSON(addr string) string {
	var b strings.Builder
	b.WriteString(`{"name":` + quote(profiles.Name(address(addr))))
	b.WriteString(`,"open":[`)
	n := 0
	openGames.ReverseIterate("", "", func(_ string, v any) bool {
		if n > 0 {
			b.WriteByte(',')
		}
		writeSummary(&b, v.(*Game))
		n++
		return n >= listLimit
	})
	var live, ended strings.Builder
	nLive, nEnded, scanned := 0, 0, 0
	games.ReverseIterate("", "", func(_ string, v any) bool {
		scanned++
		g := v.(*Game)
		switch {
		case (g.Phase == PhasePlanning || g.Phase == PhaseRevealing) && nLive < listLimit:
			if nLive > 0 {
				live.WriteByte(',')
			}
			writeSummary(&live, g)
			nLive++
		case g.Phase == PhaseFinished && nEnded < endedLimit:
			if nEnded > 0 {
				ended.WriteByte(',')
			}
			writeSummary(&ended, g)
			nEnded++
		}
		return (nLive >= listLimit && nEnded >= endedLimit) || scanned >= liveScan
	})
	b.WriteString(`],"live":[` + live.String() + `],"ended":[` + ended.String() + `],"mine":[`)
	if v := byPlayer.Get(addr); v != nil {
		for i, id := range v.([]string) {
			if i >= listLimit {
				break
			}
			if i > 0 {
				b.WriteByte(',')
			}
			writeSummary(&b, games.Get(id).(*Game))
		}
	}
	b.WriteString("]}")
	return b.String()
}

func writeSummary(b *strings.Builder, g *Game) {
	b.WriteString(`{"id":` + quote(g.ID))
	b.WriteString(`,"rev":` + strconv.Itoa(g.Rev))
	b.WriteString(`,"phase":` + quote(g.Phase.String()))
	b.WriteString(`,"turn":` + strconv.Itoa(g.Turn))
	b.WriteString(`,"maxTurns":` + strconv.Itoa(g.MaxTurns))
	b.WriteString(`,"timeout":` + strconv.FormatInt(int64(g.Timeout/time.Second), 10))
	b.WriteString(`,"winner":` + strconv.Itoa(g.Winner))
	writeVP(b, g)
	writeStakes(b, g)
	b.WriteString(`,"endReason":` + quote(g.EndReason))
	b.WriteString(`,"createdAt":` + strconv.FormatInt(g.CreatedAt.Unix(), 10))
	b.WriteString(`,"updatedAt":` + strconv.FormatInt(g.UpdatedAt.Unix(), 10))
	writeTimeoutAt(b, g)
	lockRound := int64(0)
	if g.Phase == PhasePlanning || g.Phase == PhaseRevealing {
		lockRound = g.lockRound()
	}
	b.WriteString(`,"lockRound":` + strconv.FormatInt(lockRound, 10))
	b.WriteString(`,"players":[`)
	for i, p := range g.Players {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"addr":` + quote(p.Addr.String()) + `,"name":` + quote(profiles.Name(p.Addr)) + `,"char":` + quote(p.Char) +
			`,"status":` + quote(g.State.Chars[i].Status.String()) + `,"committed":` + strconv.FormatBool(g.committed(i)) + `,"revealed":` + strconv.FormatBool(g.Revealed[i]) + `}`)
	}
	b.WriteString("]}")
}

// writeVP writes the victory points of each seat.
func writeVP(b *strings.Builder, g *Game) {
	b.WriteString(`,"vp":[`)
	for i, v := range g.VP {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(strconv.Itoa(v))
	}
	b.WriteByte(']')
}

// writeStakes writes the stake, the pot and, once paid, what each seat got.
func writeStakes(b *strings.Builder, g *Game) {
	b.WriteString(`,"stake":` + strconv.FormatInt(g.Stake, 10))
	b.WriteString(`,"pot":` + strconv.FormatInt(g.Pot, 10))
	b.WriteString(`,"payouts":[`)
	for i, v := range g.Payouts {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(strconv.FormatInt(v, 10))
	}
	b.WriteString(`],"houseCut":` + strconv.FormatInt(g.HouseCut, 10))
}

// quote encodes s as a JSON string.
func quote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b.WriteByte('\\')
			b.WriteByte(c)
		case c == '\n':
			b.WriteString(`\n`)
		case c == '\r':
			b.WriteString(`\r`)
		case c == '\t':
			b.WriteString(`\t`)
		case c < 0x20:
			b.WriteString(`\u00`)
			b.WriteByte("0123456789abcdef"[c>>4])
			b.WriteByte("0123456789abcdef"[c&0xf])
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// GameRev is the cheapest way to poll a game for changes.
func GameRev(id string) int { return getGame(id).Rev }

package gnoslinger

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/engine/v0"
	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/hex/v0"
	profiles "gno.land/r/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/profiles/v0"
)

// CreateGame opens a showdown of seats players (engine.MinPlayers to
// engine.MaxPlayers) with the caller in seat 0, playing the showdown's
// first character (engine.Setups: the marshal), standing in startHex, one
// of the hexes assigned to that character, facing f (0=N 1=NE 2=SE 3=S
// 4=SW 5=NW); it returns the game id. The other seats take the next
// characters in the order the players join. maxTurns is the game length,
// from MinMaxTurns to MaxMaxTurns; timeoutMinutes is the time each turn
// gives the players, past which anyone may claim it with ClaimTimeout, 0
// meaning DefaultTimeout (2 days). The game stays open until its seats fill
// up or its creator cancels it: the turn clock starts with the last join.
// The ugnot sent with the call are the showdown's stake, which every
// joiner must send too; none, a free showdown (stakes.gno).
func CreateGame(cur realm, seats int, maxTurns int, timeoutMinutes int, startHex string, facing int) string {
	caller := cur.Previous().Address()
	stake := sentStake(cur)
	if seats < engine.MinPlayers || seats > engine.MaxPlayers {
		panic("gnoslinger: seats must be between " + strconv.Itoa(engine.MinPlayers) + " and " + strconv.Itoa(engine.MaxPlayers))
	}
	if maxTurns < MinMaxTurns || maxTurns > MaxMaxTurns {
		panic("gnoslinger: maxTurns must be between " + strconv.Itoa(MinMaxTurns) + " and " + strconv.Itoa(MaxMaxTurns))
	}
	timeout := DefaultTimeout
	if timeoutMinutes != 0 {
		timeout = time.Duration(timeoutMinutes) * time.Minute
	}
	if timeout < MinTimeout || timeout > MaxTimeout {
		panic("gnoslinger: timeoutMinutes must be between " + strconv.Itoa(int(MinTimeout/time.Minute)) + " and " + strconv.Itoa(int(MaxTimeout/time.Minute)))
	}
	charKey := engine.SeatChar(0)
	assertSetUp(charKey, startHex, facing)
	id := gameSeq.Next().String()
	g := &Game{
		ID:        id,
		Players:   make([]Player, seats),
		State:     engine.NewState(seats),
		Turn:      1,
		MaxTurns:  maxTurns,
		Timeout:   timeout,
		Phase:     PhaseWaiting,
		Missed:    make([]int, seats),
		Winner:    -1,
		VP:        make([]int, seats),
		Stake:     stake,
		Pot:       stake,
		CreatedAt: time.Now(),
	}
	g.clearTurn()
	g.Players[0] = Player{Addr: caller, Char: charKey}
	g.State.SetUp(0, startHex, hex.Dir(facing))
	openGames.Set(id, g)
	index(caller, id)
	profiles.Ensure(cross(cur), caller)
	save(g)
	emit("GameCreated", "id", id, "creator", caller.String(), "char", charKey, "seats", strconv.Itoa(seats),
		"maxTurns", strconv.Itoa(maxTurns), "timeoutMinutes", strconv.Itoa(int(timeout/time.Minute)), "hex", startHex, "facing", strconv.Itoa(facing),
		"stake", strconv.FormatInt(stake, 10))
	return id
}

// JoinGame seats the caller in the first free seat of a waiting game,
// playing that seat's character (the kid, then the reb, then the yankee),
// standing in startHex, one of that character's hexes, facing f; the game
// starts collecting the commits of turn 1 once its last seat is taken.
// The call must send the showdown's stake, no more, no less.
func JoinGame(cur realm, id string, startHex string, facing int) {
	caller := cur.Previous().Address()
	stake := sentStake(cur)
	g := getGame(id)
	if g.Phase != PhaseWaiting {
		panic("gnoslinger: game is not open")
	}
	switch g.seat(caller) {
	case 0:
		panic("gnoslinger: you cannot join your own game")
	case -1:
	default:
		panic("gnoslinger: you are already in this game")
	}
	seat := g.freeSeat()
	if seat < 0 {
		panic("gnoslinger: every seat is taken")
	}
	charKey := engine.SeatChar(seat)
	assertSetUp(charKey, startHex, facing)
	if stake != g.Stake {
		panic("gnoslinger: this showdown's stake is " + strconv.FormatInt(g.Stake, 10) + Denom + ", sent " + strconv.FormatInt(stake, 10) + Denom)
	}
	g.Pot += stake
	g.Players[seat] = Player{Addr: caller, Char: charKey}
	g.State.SetUp(seat, startHex, hex.Dir(facing))
	index(caller, id)
	if g.freeSeat() < 0 {
		// The game starts: it counts as played for every seat.
		g.Phase = PhasePlanning
		g.startTurn()
		g.notifyPlanDue()
		openGames.Remove(id)
		for _, p := range g.Players {
			profiles.AddGamePlayed(cross(cur), p.Addr)
		}
	} else {
		profiles.Ensure(cross(cur), caller)
	}
	save(g)
	emit("PlayerJoined", "id", id, "player", caller.String(), "seat", strconv.Itoa(seat), "char", charKey, "hex", startHex, "facing", strconv.Itoa(facing))
}

// assertSetUp refuses a character that is not in the showdown, a hex it
// may not set up in, or no such facing.
func assertSetUp(charKey, startHex string, facing int) {
	setup := engine.SetupOf(charKey)
	if setup == nil {
		panic("gnoslinger: " + charKey + " is not in this showdown: play " + strings.Join(engine.ShowdownChars(), " or "))
	}
	if !engine.CanSetUp(charKey, startHex) {
		panic("gnoslinger: " + charKey + " sets up in " + strings.Join(setup.Hexes, ", ") + ", not in " + startHex)
	}
	if !hex.Dir(facing).Valid() {
		panic("gnoslinger: facing must be between 0 (N) and 5 (NW)")
	}
}

// CancelGame withdraws a game whose seats are not all taken yet. Creator
// only. The game is deleted, not kept as finished, so the creator gets back
// the storage deposit CreateGame paid; the players who had joined are
// unindexed with it, and every stake paid goes back.
func CancelGame(cur realm, id string) {
	assertNoSend()
	caller := cur.Previous().Address()
	g := getGame(id)
	if g.Phase != PhaseWaiting {
		panic("gnoslinger: only a game waiting for players can be cancelled")
	}
	if g.Players[0].Addr != caller {
		panic("gnoslinger: only the creator can cancel the game")
	}
	g.refundStakes(cur)
	openGames.Remove(id)
	games.Remove(id)
	for _, p := range g.Players {
		if p.Addr != "" {
			unindex(p.Addr, id)
		}
	}
	emit("GameEnded", "id", id, "reason", "cancelled", "winner", "")
	g.notifyCancelled(caller)
}

package gnoslinger

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/engine/v0"
	gnotif "gno.land/r/nym-gfanton001/gnotif/v1"
)

// Browser notifications, through gnotif (https://gnotif.xyz). At the
// moments a player may have the game closed, the realm emits one event per
// player concerned, naming it in the "to" attribute (PlanDue, RevealDue,
// ShowdownOver), and declares in the gnotif registry one trigger per
// event, which gives the notification its title, body and link. A gnotif
// server (gnotif.xyz on Onyx; make notif runs one on gnodev) reads the
// chain's events and pushes the notification to every browser opted in
// with that address; the client opts in from the lobby
// (game/notifications.ts). A deadline passing emits nothing, so a timeout
// is never notified.

// notifTriggers are the realm's triggers, by name. Title and body are
// templates, {key} standing for the event's attribute: every event names
// the player's character (char) and the others' (vs), and the game; the
// link opens the game in the client (game/route.ts).
var notifTriggers = []struct {
	name string
	t    gnotif.Trigger
}{
	{"move", gnotif.Trigger{Event: "PlanDue", Param: "to", Title: "Gnoslinger · Your move", Body: "{char} vs {vs}, game {id}, turn {turn} of {turns}: {left} to send your plan.", Link: "/#game/{id}"}},
	{"reveal", gnotif.Trigger{Event: "RevealDue", Param: "to", Title: "Gnoslinger · Reveal your plan", Body: "{char} vs {vs}, game {id}, turn {turn} of {turns}: every plan is in, yours waits to be revealed.", Link: "/#game/{id}"}},
	{"over", gnotif.Trigger{Event: "ShowdownOver", Param: "to", Title: "Gnoslinger · Showdown over", Body: "{char} vs {vs}, game {id}: {outcome}.", Link: "/#game/{id}"}},
}

// notif is the realm's handle on its triggers in the registry, kept so that
// DeclareTriggers can set them again: a changed title, body or link keeps
// the trigger's id, and so the browsers opted in.
var notif *gnotif.Handle

// DeclareTriggers sets the realm's triggers in the gnotif registry. Admin
// only, and the first call has what the registry's Open requires: the
// namespace owner's own key (not a session), in a call sent straight to
// the realm; so the deployer sends it once the realm is deployed (on
// gnodev, the make notif script sends it as test1). The triggers keep
// their ids from one call to the next. Every call makes the registry emit
// each trigger again (TriggerDeclared), which is what a gnotif server
// reads them from: the registry emits nothing for a trigger set as it
// already is, so each is first set with a nudged body, then as it should
// be. That is for gnodev, whose reload puts the earlier call in the
// genesis, where no indexer serves its events: the script calls again
// after each reload and the triggers reach gnotifd anew.
func DeclareTriggers(cur realm) {
	assertNoSend()
	assertAdmin(cur)
	me := cur.Sub(gnotif.Subpath)
	if notif == nil {
		notif = gnotif.Open(cross(me))
	}
	for _, nt := range notifTriggers {
		nudged := nt.t
		nudged.Body += " "
		notif.Set(cross(me), nt.name, nudged)
		notif.Set(cross(me), nt.name, nt.t)
	}
}

// notifyPlanDue tells every player with a plan to send that the turn
// started: its character in the fight, not committed, with time points to
// play (one passed automatically has nothing to send).
func (g *Game) notifyPlanDue() {
	if g.Phase != PhasePlanning {
		return
	}
	left := formatTimeout(g.Timeout)
	for p, pl := range g.Players {
		if g.State.Chars[p].Status == engine.Alive && !g.committed(p) && g.State.Budget(p) > 0 {
			emit("PlanDue", "id", g.ID, "turn", strconv.Itoa(g.Turn), "turns", strconv.Itoa(g.MaxTurns), "to", pl.Addr.String(), "char", charName(pl.Char), "vs", g.others(p), "left", left)
		}
	}
}

// notifyRevealDue tells every player whose committed plan is not revealed
// yet that the reveals started.
func (g *Game) notifyRevealDue() {
	for p, pl := range g.Players {
		if g.State.Chars[p].Status == engine.Alive && !g.Revealed[p] {
			emit("RevealDue", "id", g.ID, "turn", strconv.Itoa(g.Turn), "turns", strconv.Itoa(g.MaxTurns), "to", pl.Addr.String(), "char", charName(pl.Char), "vs", g.others(p))
		}
	}
}

// notifyOver tells every player how the finished showdown ended for it.
func (g *Game) notifyOver() {
	for p, pl := range g.Players {
		outcome := "a draw"
		switch {
		case g.Winner == p:
			outcome = "you won"
		case g.Winner >= 0:
			outcome = "you lost"
		}
		emit("ShowdownOver", "id", g.ID, "to", pl.Addr.String(), "char", charName(pl.Char), "vs", g.others(p), "outcome", outcome)
	}
}

// notifyCancelled tells the players who had joined a showdown that its
// creator cancelled it (the creator knows).
func (g *Game) notifyCancelled(creator address) {
	for p, pl := range g.Players {
		if pl.Addr != "" && pl.Addr != creator {
			emit("ShowdownOver", "id", g.ID, "to", pl.Addr.String(), "char", charName(pl.Char), "vs", g.others(p), "outcome", "cancelled by its creator, every stake given back")
		}
	}
}

// others names the characters of the other seated players, in seat
// order, comma-separated: "The Kid, Reb".
func (g *Game) others(seat int) string {
	var names []string
	for p, pl := range g.Players {
		if p != seat && pl.Addr != "" {
			names = append(names, charName(pl.Char))
		}
	}
	return strings.Join(names, ", ")
}

// charName spells a character key as the client does: "the_kid" is "The
// Kid".
func charName(key string) string {
	words := strings.Split(key, "_")
	for i, w := range words {
		if w != "" {
			words[i] = strings.ToUpper(w[:1]) + w[1:]
		}
	}
	return strings.Join(words, " ")
}

// formatTimeout spells the time a turn gives: whole days, else whole hours,
// else minutes.
func formatTimeout(d time.Duration) string {
	n, unit := int64(d/time.Minute), "minute"
	switch {
	case d%(24*time.Hour) == 0:
		n, unit = int64(d/(24*time.Hour)), "day"
	case d%time.Hour == 0:
		n, unit = int64(d/time.Hour), "hour"
	}
	if n != 1 {
		unit += "s"
	}
	return strconv.FormatInt(n, 10) + " " + unit
}

package gnoslinger

import (
	"chain/runtime"
	enchex "encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/cards/v0"
	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/engine/v0"
	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/hex/v0"
)

// Commit seals the caller's plan for the given turn, the one in progress,
// and returns the game revision (a commit meant for another turn, say one
// still on its way when time was called, is refused: its hash, which covers
// the turn, could never be revealed in this one, and it would take the
// seat's commit). hash is PlanHash of a salt and the plan, which a Reveal shows
// once every character still in the fight committed; locked is the salt
// and plan timelocked to the turn's LockRound (at most MaxLocked bytes,
// required: encrypting needs no drand node), which anyone can open and
// reveal from then if the player does not. When this commit is the last one the turn waits for, the game
// moves on to the reveals.
func Commit(cur realm, id string, turn int, hash string, locked string) int {
	assertNoSend()
	caller := cur.Previous().Address()
	g := getGame(id)
	if turn != g.Turn {
		panic("gnoslinger: turn " + strconv.Itoa(turn) + " is not the turn in progress")
	}
	if g.Phase != PhasePlanning {
		panic("gnoslinger: game is not accepting plans")
	}
	g.assertInTime()
	p := g.mustSeat(caller)
	if g.State.Chars[p].Status != engine.Alive {
		panic("gnoslinger: your character is out of the fight")
	}
	if g.committed(p) {
		panic("gnoslinger: plan already submitted for this turn")
	}
	if !isHex(hash, 64, 64) {
		panic("gnoslinger: the hash must be 64 hex characters")
	}
	if locked == "" {
		panic("gnoslinger: a commit needs its timelocked plan")
	}
	if len(locked) > MaxLocked {
		panic("gnoslinger: the timelocked plan is over " + strconv.Itoa(MaxLocked) + " bytes")
	}
	g.Commits[p] = Sealed{Hash: hash, Locked: locked}
	emit("PlanCommitted", "id", id, "turn", strconv.Itoa(g.Turn), "player", caller.String(), "seat", strconv.Itoa(p))
	progress(cur, g)
	save(g)
	return g.Rev
}

// Reveal puts a seat's salt and plan for the given turn on chain and
// returns the game revision. Anyone may send it while the game collects the
// reveals: the salt and plan must match the seat's commit (PlanHash). The
// last seat to commit may also reveal straight away, without committing:
// the others' plans are already fixed by their hashes, so its plan in clear
// helps nobody; that is only accepted from the seat itself, before the
// deadline, once every other character still in the fight committed (a
// refused transaction still shows its plan). The plan is a comma-separated
// list of "<card><f|b>[:<choice>]" entries, e.g. "1f:ahead_left,2f:ahead,3f";
// an empty string passes. The reveal that completes the turn resolves it in
// this same transaction and the next turn starts.
func Reveal(cur realm, id string, turn int, seat int, salt string, plan string) int {
	assertNoSend()
	caller := cur.Previous().Address()
	g := getGame(id)
	if turn != g.Turn {
		panic("gnoslinger: turn " + strconv.Itoa(turn) + " is not the turn in progress")
	}
	if seat < 0 || seat >= g.seats() {
		panic("gnoslinger: there is no seat " + strconv.Itoa(seat) + " in this game")
	}
	switch g.Phase {
	case PhaseRevealing:
		if g.Revealed[seat] {
			panic("gnoslinger: that plan is already revealed")
		}
		revealSeat(g, seat, salt, plan, caller)
	case PhasePlanning:
		// The last commit, in clear.
		g.assertInTime()
		if g.mustSeat(caller) != seat {
			panic("gnoslinger: only its player may reveal a plan before every plan is committed")
		}
		if g.State.Chars[seat].Status != engine.Alive {
			panic("gnoslinger: your character is out of the fight")
		}
		if g.committed(seat) {
			panic("gnoslinger: plan already submitted for this turn")
		}
		for p := range g.Players {
			if p != seat && g.State.Chars[p].Status == engine.Alive && !g.committed(p) {
				panic("gnoslinger: only the last plan to commit may be revealed at once")
			}
		}
		storePlan(g, seat, salt, plan, caller)
	default:
		panic("gnoslinger: game is not accepting plans")
	}
	progress(cur, g)
	save(g)
	return g.Rev
}

// RevealMany reveals several seats of the given turn in one transaction,
// as Reveal does each, in the order given: what an opener of the
// timelocked plans sends. seats, salts and plans are lists separated by
// ";", of the same length (a plan string never holds a ";", an empty plan
// is an empty field). A seat already revealed is skipped (its player's own
// reveal landed first), and so is one whose salt and plan do not match its
// commit or whose plan is not valid (event PlanUnopened): the opener
// cannot check that before opening, and one bad timelocked plan must not
// keep the others back; that seat stays unrevealed, for the claim.
func RevealMany(cur realm, id string, turn int, seats string, salts string, plans string) int {
	assertNoSend()
	caller := cur.Previous().Address()
	g := getGame(id)
	if turn != g.Turn {
		panic("gnoslinger: turn " + strconv.Itoa(turn) + " is not the turn in progress")
	}
	if g.Phase != PhaseRevealing {
		panic("gnoslinger: game is not collecting the reveals")
	}
	ss, sa, pl := strings.Split(seats, ";"), strings.Split(salts, ";"), strings.Split(plans, ";")
	if len(sa) != len(ss) || len(pl) != len(ss) {
		panic("gnoslinger: seats, salts and plans must list as many entries")
	}
	for i, s := range ss {
		seat, err := strconv.Atoi(s)
		if err != nil || seat < 0 || seat >= g.seats() {
			panic("gnoslinger: there is no seat " + s + " in this game")
		}
		if g.Revealed[seat] {
			continue
		}
		if why := checkReveal(g, seat, sa[i], pl[i]); why != "" {
			emit("PlanUnopened", "id", g.ID, "turn", strconv.Itoa(g.Turn), "seat", s, "reason", why)
			continue
		}
		revealSeat(g, seat, sa[i], pl[i], caller)
	}
	progress(cur, g)
	save(g)
	return g.Rev
}

// revealSeat checks a committed seat's salt and plan against its hash and
// stores them, clearing the commit.
func revealSeat(g *Game, seat int, salt, plan string, by address) {
	if why := checkReveal(g, seat, salt, plan); why != "" {
		panic("gnoslinger: " + why)
	}
	storePlan(g, seat, salt, plan, by)
}

// checkReveal tells why a committed seat's salt and plan cannot be
// revealed, "" if they can.
func checkReveal(g *Game, seat int, salt, plan string) string {
	if g.Commits[seat].Hash == "" {
		return "seat " + strconv.Itoa(seat) + " has no plan committed"
	}
	if PlanHash(g.ID, g.Turn, seat, salt, plan) != g.Commits[seat].Hash {
		return "the salt and plan do not match seat " + strconv.Itoa(seat) + "'s commit"
	}
	if _, why := checkPlan(g, seat, salt, plan); why != "" {
		return why
	}
	return ""
}

// checkPlan parses and validates a seat's salt and plan; why is "" when
// they are fine.
func checkPlan(g *Game, seat int, salt, plan string) (pl engine.Plan, why string) {
	if !isHex(salt, 1, MaxSalt) {
		return nil, "the salt must be 1 to " + strconv.Itoa(MaxSalt) + " hex characters"
	}
	pl, err := engine.ParsePlan(plan)
	if err != nil {
		return nil, err.Error()
	}
	if err := pl.Validate(g.State.Chars[seat]); err != nil {
		return nil, err.Error()
	}
	for _, a := range pl {
		if a.Ground > 0 && !groundExists(g.State, a.Ground) {
			return nil, "there is no such weapon on the ground"
		}
		if a.Target >= g.seats() {
			return nil, "there is no character @" + strconv.Itoa(a.Target) + " in this game"
		}
		if a.Target == seat {
			return nil, "you cannot " + a.Opt + " at your own character"
		}
	}
	return pl, ""
}

// storePlan validates a seat's plan and records it as revealed, clearing
// its commit (whose storage deposit goes back to the caller).
func storePlan(g *Game, seat int, salt, plan string, by address) {
	pl, why := checkPlan(g, seat, salt, plan)
	if why != "" {
		panic("gnoslinger: " + why)
	}
	// Target-status flags for this turn, set whether or not the actions
	// end up executing ([H12]).
	g.State.Chars[seat].PlayedFoot = pl.PlayedFoot()
	g.State.Chars[seat].PlayedRun = pl.Has(cards.Run)
	g.Plans[seat] = pl.String()
	g.Salts[seat] = salt
	g.Revealed[seat] = true
	g.Missed[seat] = 0
	g.Commits[seat] = Sealed{}
	emit("PlanRevealed", "id", g.ID, "turn", strconv.Itoa(g.Turn), "seat", strconv.Itoa(seat), "by", by.String())
}

// isHex reports whether s is min to max lowercase hex characters.
func isHex(s string, min, max int) bool {
	if len(s) < min || len(s) > max {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// progress moves the turn on as far as it can: it passes the players who
// cannot play anything (a carried delay of 5 or more leaves no time
// points, rule 7.3: there is nothing to wait for from them), goes on to
// the reveals once every character in the fight committed, and resolves
// the turn once every plan is in; when nobody is left to wait for in the
// next turn either, that turn resolves at once, and so on.
func progress(cur realm, g *Game) {
	for {
		if g.Phase == PhasePlanning {
			for p := range g.Players {
				c := &g.State.Chars[p]
				if c.Status != engine.Alive || g.committed(p) || g.State.Budget(p) > 0 {
					continue
				}
				c.PlayedFoot = false
				c.PlayedRun = false
				g.Plans[p] = ""
				g.Revealed[p] = true
				emit("PlanPassed", "id", g.ID, "turn", strconv.Itoa(g.Turn), "seat", strconv.Itoa(p))
			}
			if !g.allCommitted() {
				return
			}
			g.Phase = PhaseRevealing
			emit("AllCommitted", "id", g.ID, "turn", strconv.Itoa(g.Turn))
			g.notifyRevealDue()
		}
		if g.Phase != PhaseRevealing || !g.allRevealed() {
			return
		}
		turn := g.Turn
		seed := resolveTurn(cur, g)
		emit("TurnResolved", "id", g.ID, "turn", strconv.Itoa(turn), "rev", strconv.Itoa(g.Rev+1), "seed", seed)
		g.notifyPlanDue()
	}
}

// resolveTurn plays the seats' plans with the result deck shuffled from
// this turn's seed, stores the result and advances the game. It returns the
// seed in hex.
func resolveTurn(cur realm, g *Game) string {
	n := g.seats()
	// The salts make the seed unknown to every player when it commits, the
	// block keeps the outcome unknown to the last one to reveal.
	parts := append([]string{realmPath, g.ID, strconv.Itoa(g.Turn)}, g.Salts...)
	parts = append(parts, g.Plans...)
	parts = append(parts, strconv.FormatInt(runtime.ChainHeight(), 10), strconv.FormatInt(time.Now().UnixNano(), 10))
	seed := engine.Seed(parts...)
	plans := make([]engine.Plan, n)
	for i, s := range g.Plans {
		pl, err := engine.ParsePlan(s)
		if err != nil {
			panic("gnoslinger: stored plan is invalid: " + err.Error())
		}
		plans[i] = pl
	}
	// From a copy: the live state may share the characters with what the
	// engine returns (see engine.CloneChars).
	start := engine.CloneChars(g.State.Chars)
	ground := engine.EncodeGround(g.State.Ground)
	deck := engine.NewDeck(seed)
	st, evs := engine.Resolve(hex.A, g.State, plans, deck)
	st, endEvs := engine.EndTurn(st)
	evs = append(evs, endEvs...)
	if g.Turn >= g.MaxTurns && engine.AliveCount(st) > 1 { // the end-of-showdown SERIOUS wound check (14.5)
		st, endEvs = engine.EndShowdown(st, deck)
		evs = append(evs, endEvs...)
	}
	// Victory points close the turn: what it did, then, when the showdown
	// ends with it, the end of the showdown (rule 15).
	over := engine.AliveCount(st) <= 1 || g.Turn >= g.MaxTurns
	awards := engine.TurnVictoryPoints(engine.State{Chars: start}, st)
	if over {
		awards = append(awards, engine.EndVictoryPoints(st)...)
	}
	evs = append(evs, engine.VPEvents(awards)...)
	seedHex := enchex.EncodeToString(seed[:])
	g.Turns = append(g.Turns, newTurnResult(g.Turn, start, ground, g.Plans, seedHex, deck.Drawn(), evs))
	g.State = st
	g.award(cur, awards)
	g.clearTurn()
	switch {
	case engine.AliveCount(g.State) == 0:
		g.finish(cur, "all_down")
	case engine.AliveCount(g.State) == 1:
		g.finish(cur, "last_standing")
	case g.Turn >= g.MaxTurns:
		g.finish(cur, "max_turns")
	default:
		g.Turn++
		g.Phase = PhasePlanning
		g.startTurn()
	}
	return seedHex
}

// groundExists reports whether a gun with that ground id lies somewhere on
// the board; whether it is in the character's hex is checked when the
// action executes, since the character may walk to it first.
func groundExists(st engine.State, id int) bool {
	for _, gg := range st.Ground {
		if gg.ID == id {
			return true
		}
	}
	return false
}

// Surrender gives up the showdown (rule 15.4: at the start of a turn, that
// is while the plans are committed; once they are revealed, surrendering
// after reading the others' would be the abort the hidden plans remove).
// The character is Out: nobody can shoot it and it plays no more. With one
// character left in the fight the game ends and is scored, the surrendered
// losing the "Surrender" points and, an enemy holding the field, being
// captured; with more, the showdown goes on without it (its commit is
// dropped), and goes on to the reveals if the others' plans are committed.
func Surrender(cur realm, id string) {
	assertNoSend()
	caller := cur.Previous().Address()
	g := getGame(id)
	switch g.Phase {
	case PhasePlanning:
	case PhaseRevealing:
		panic("gnoslinger: the plans are being revealed: surrender at the start of a turn")
	default:
		panic("gnoslinger: game is not in progress")
	}
	p := g.mustSeat(caller)
	if g.State.Chars[p].Status != engine.Alive {
		panic("gnoslinger: your character is out of the fight")
	}
	g.State.Chars[p].Status = engine.Out
	emit("PlayerSurrendered", "id", id, "turn", strconv.Itoa(g.Turn), "player", caller.String(), "seat", strconv.Itoa(p))
	if engine.AliveCount(g.State) <= 1 {
		g.award(cur, engine.EndVictoryPoints(g.State))
		g.finish(cur, "surrender")
	} else {
		g.Commits[p] = Sealed{}
		g.Plans[p] = ""
		g.Salts[p] = ""
		g.Revealed[p] = false
		progress(cur, g)
	}
	save(g)
}

// ClaimTimeout ends the wait of a turn past its deadline. Anyone may call
// it. A game waiting for players has no timeout (its creator may cancel
// it). While the plans are committed, past the deadline: each player who
// did not commit misses the turn: it is passed for them, unless that makes
// MaxMissed in a row, which puts the character out of the fight (out of
// time counts as surrendering); the game then goes on to the reveals, and
// with nobody's plan in, the turn resolves empty. A showdown nobody plays
// any more so ends after MaxMissed claims, everyone out of the fight (its
// stakes given back, stakes.gno). While they are
// revealed, RevealGrace past the deadline (the timelocked plans had time
// to be opened, which is how a vanished player's plan normally comes in):
// every character whose plan is still not in misses the turn the same way.
// The realm cannot tell a copy nobody could open from one nobody tried to
// open, so it does not punish more than a missed turn. With one character
// left the game ends and is scored, with more the turn resolves with the
// plans in and the showdown goes on.
func ClaimTimeout(cur realm, id string) {
	assertNoSend()
	g := getGame(id)
	switch g.Phase {
	case PhaseFinished:
		panic("gnoslinger: game is finished")
	case PhaseWaiting:
		panic("gnoslinger: the game is waiting for players: it has no timeout")
	}
	if time.Now().Before(g.timeoutAt()) {
		if g.Phase == PhaseRevealing {
			panic("gnoslinger: the plans can still be revealed")
		}
		panic("gnoslinger: the game has not timed out yet")
	}
	for p := range g.Players {
		late := !g.committed(p) // planning: no commit
		if g.Phase == PhaseRevealing {
			late = !g.Revealed[p] // revealing: no plan in
		}
		if g.State.Chars[p].Status == engine.Alive && late {
			missTurn(g, p)
		}
	}
	if engine.AliveCount(g.State) <= 1 {
		g.award(cur, engine.EndVictoryPoints(g.State))
		g.finish(cur, "timeout")
	} else {
		progress(cur, g)
	}
	save(g)
}

// missTurn passes the turn for a seat whose plan is not in at the claim
// (its commit, if any, dropped), or puts the character out of the fight
// at its MaxMissed-th miss in a row; only a revealed plan resets the count.
func missTurn(g *Game, p int) {
	c := &g.State.Chars[p]
	g.Missed[p]++
	g.Commits[p] = Sealed{}
	emit("PlanMissed", "id", g.ID, "turn", strconv.Itoa(g.Turn), "seat", strconv.Itoa(p), "missed", strconv.Itoa(g.Missed[p]))
	if g.Missed[p] >= MaxMissed {
		c.Status = engine.Out
		return
	}
	c.PlayedFoot = false
	c.PlayedRun = false
	g.Plans[p] = ""
	g.Revealed[p] = true
}

package gnoslinger

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/cards/v0"
	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/engine/v0"
	"gno.land/p/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/hex/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
	profiles "gno.land/r/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/profiles/v0"
)

const recentLimit = 20

var router = mux.NewRouter()

func init() {
	router.HandleFunc("", renderHome)
	router.HandleFunc("help", renderHelp)
	router.HandleFunc("game/{id}", renderGame)
	router.HandleFunc("json/game/{id}", func(res *mux.ResponseWriter, req *mux.Request) {
		res.Write(GameJSON(req.GetVar("id")))
	})
	router.HandleFunc("json/games/{addr}", func(res *mux.ResponseWriter, req *mux.Request) {
		res.Write(GamesJSON(req.GetVar("addr")))
	})
	router.HandleFunc("json/history/{id}/{turn}", func(res *mux.ResponseWriter, req *mux.Request) {
		turn, err := strconv.Atoi(req.GetVar("turn"))
		if err != nil {
			panic("gnoslinger: invalid turn")
		}
		res.Write(TurnJSON(req.GetVar("id"), turn))
	})
	router.HandleFunc("json/plan/{id}/{addr}", func(res *mux.ResponseWriter, req *mux.Request) {
		res.Write(PlanJSON(req.GetVar("id"), req.GetVar("addr")))
	})
}

// Render serves the gnoweb pages ("", "help", "game/{id}") and the raw JSON
// views the web client reads ("json/game/{id}", "json/games/{addr}",
// "json/history/{id}/{turn}", "json/plan/{id}/{addr}"); the players' profiles and
// ranking are the profiles realm's (gno.land/r/g1th0masp67zfs9lg6d34qhghldhg6kjcqjuv7c2/gnoslinger/profiles/v0).
func Render(path string) string {
	return router.Render(path)
}

// link is a gnoweb link to a sub-path of this realm.
func link(text, path string) string {
	return md.Link(text, strings.TrimPrefix(realmPath, "gno.land")+":"+path)
}

func renderHome(res *mux.ResponseWriter, _ *mux.Request) {
	res.Write(md.H1("Gnoslinger"))
	res.Write(md.Paragraph("Showdowns of two to four gunfighters on board A, the Corral, each on their own. " +
		"Create a game, wait for the seats to fill up, then submit a plan every turn. " +
		link("How to play", "help") + "."))
	res.Write(md.Paragraph(createLink("Create a game of two as the marshal", 2) + " · " + createLink("of three", 3) + " · " + createLink("of four", 4)))

	res.Write(md.H2("Open games"))
	n := 0
	var b strings.Builder
	b.WriteString("| Game | Creator | Seats | Stake | Created | |\n|---|---|---|---|---|---|\n")
	openGames.ReverseIterate("", "", func(_ string, v any) bool {
		g := v.(*Game)
		b.WriteString("| " + link(g.ID, "game/"+g.ID) +
			" | " + addr(g.Players[0].Addr) +
			" | " + strconv.Itoa(g.seated()) + "/" + strconv.Itoa(g.seats()) +
			" | " + stakeLabel(g) +
			" | " + when(g.CreatedAt) +
			" | " + joinLink(g) + " |\n")
		n++
		return n >= recentLimit
	})
	if n == 0 {
		res.Write(md.Paragraph("No game is waiting for players."))
	} else {
		res.Write(b.String() + "\n")
	}

	res.Write(md.H2("Recent games"))
	n = 0
	b.Reset()
	b.WriteString("| Game | Players | Turn | Phase |\n|---|---|---|---|\n")
	games.ReverseIterate("", "", func(_ string, v any) bool {
		g := v.(*Game)
		b.WriteString("| " + link(g.ID, "game/"+g.ID) +
			" | " + seatLabels(g) +
			" | " + strconv.Itoa(g.Turn) + "/" + strconv.Itoa(g.MaxTurns) +
			" | " + phaseLabel(g) + " |\n")
		n++
		return n >= recentLimit
	})
	if n == 0 {
		res.Write(md.Paragraph("No game yet."))
	} else {
		res.Write(b.String() + "\n")
	}
	if house > 0 {
		res.Write(md.Paragraph("The house holds " + gnot(house) + " for events."))
	}
}

func renderGame(res *mux.ResponseWriter, req *mux.Request) {
	g := getGame(req.GetVar("id"))
	res.Write(md.H1("Game " + g.ID))
	res.Write(md.Paragraph("Turn " + strconv.Itoa(g.Turn) + " of " + strconv.Itoa(g.MaxTurns) + " · " + phaseLabel(g)))
	if g.Stake > 0 {
		line := "Stake " + stakeLabel(g) + " · pot " + gnot(g.Pot)
		for i, v := range g.Payouts {
			if v > 0 {
				line += " · " + addr(g.Players[i].Addr) + " got " + gnot(v)
			}
		}
		if g.HouseCut > 0 {
			line += " · the house kept " + gnot(g.HouseCut)
		}
		res.Write(md.Paragraph(line))
	}

	var b strings.Builder
	b.WriteString("| Seat | Player | Character | Hex | Facing | Down | Delay | Status | Plan |\n")
	b.WriteString("|---|---|---|---|---|---|---|---|---|\n")
	for i, p := range g.Players {
		c := g.State.Chars[i]
		plan := "-"
		if g.Phase == PhasePlanning || g.Phase == PhaseRevealing {
			switch {
			case g.Revealed[i]:
				plan = "revealed"
			case g.committed(i):
				plan = "committed"
			default:
				plan = "pending"
			}
		}
		b.WriteString("| " + strconv.Itoa(i) +
			" | " + addr(p.Addr) +
			" | " + sanitize.InlineText(p.Char) +
			" | " + c.Hex +
			" | " + c.Facing.String() +
			" | " + yesNo(c.Down) +
			" | " + strconv.Itoa(c.Delay) +
			" | " + c.Status.String() +
			" | " + plan + " |\n")
	}
	res.Write(b.String() + "\n")

	for _, r := range g.Turns {
		res.Write(md.H3("Turn " + strconv.Itoa(r.Turn)))
		plans := make([]string, len(r.Plans))
		for i, p := range r.Plans {
			plans[i] = md.InlineCode(orPass(p))
		}
		res.Write(md.Paragraph("Plans: " + strings.Join(plans, " vs ")))
		if drawn := r.Cards(); len(drawn) > 0 {
			cards := make([]string, len(drawn))
			for i, n := range drawn {
				cards[i] = strconv.Itoa(n)
			}
			res.Write(md.Paragraph("Result cards drawn: " + strings.Join(cards, ", ")))
		}
		evs := r.Events()
		items := make([]string, 0, len(evs))
		for _, e := range evs {
			items = append(items, describeEvent(g, e))
		}
		if len(items) == 0 {
			items = append(items, "Nothing happened.")
		}
		res.Write(md.BulletList(items) + "\n")
	}

	switch g.Phase {
	case PhaseWaiting:
		res.Write(md.Paragraph(joinLink(g) + " · " + md.Link("Cancel", txlink.Call("CancelGame", "id", g.ID))))
	case PhasePlanning:
		res.Write(md.Paragraph("Plans are hidden: commit " + md.InlineCode("PlanHash(id, turn, seat, salt, plan)") +
			", reveal once every plan is committed. " +
			md.Link("Commit a plan", txlink.Call("Commit", "id", g.ID, "turn", strconv.Itoa(g.Turn), "hash", "", "locked", "")) +
			" · " + md.Link("Surrender", txlink.Call("Surrender", "id", g.ID)) +
			" · " + md.Link("Claim timeout", txlink.Call("ClaimTimeout", "id", g.ID)) +
			" (after " + when(g.timeoutAt()) + ")"))
	case PhaseRevealing:
		res.Write(md.Paragraph(md.Link("Reveal a plan", txlink.Call("Reveal", "id", g.ID, "turn", strconv.Itoa(g.Turn), "seat", "", "salt", "", "plan", "")) +
			" · " + md.Link("Claim timeout", txlink.Call("ClaimTimeout", "id", g.ID)) +
			" (after " + when(g.timeoutAt()) + ")"))
	}
	res.Write(md.Paragraph(link("Back to the lobby", "")))
}

